def brl(c) -> str:
    if c is None:
        return "—"
    v = round(c) / 100
    s = f"{v:,.0f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return f"R$ {s}"


def pct(x) -> str:
    return "—" if x is None else (f"{x * 100:.1f}%".replace(".", ",") if x <= 10 else f"{x * 100:.0f}% (>100%: inalcançável)")


